import json, urllib.request
for repo in ['xlsx2csv','pandas']:
 url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=12&onlyActiveTags=true'
 try:
  d=json.load(urllib.request.urlopen(url,timeout=20))
  print(repo,[t['name'] for t in d.get('tags',[])[:12]])
 except Exception as e: print(repo,type(e).__name__,str(e)[:120])
PY"

