item.command:
/bin/bash -lc "python - <<'PY'
import json,urllib.request,urllib.error
for repo in ['openpyxl','python-calamine','r-readxl','xlsx2csv']:
 for suffix in ['?limit=20&onlyActiveTags=true','']:
  url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/{suffix}' if suffix else f'https://quay.io/api/v1/repository/biocontainers/{repo}'
  try:
   req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'})
   d=json.load(urllib.request.urlopen(req,timeout=20))
   if 'tags' in d: print(repo,[t['name'] for t in d['tags'][:10]])
   else: print(repo,'repository exists',d.get('name'))
   break
  except Exception as e:
   if suffix=='': print(repo,type(e).__name__,str(e)[:80])
PY"

/bin/bash -lc "python - <<'PY'
import json,urllib.request,urllib.error
for repo in ['openpyxl','python-calamine','r-readxl','xlsx2csv']:
 for suffix in ['?limit=20&onlyActiveTags=true','']:
  url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/{suffix}' if suffix else f'https://quay.io/api/v1/repository/biocontainers/{repo}'
  try:
   req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'})
   d=json.load(urllib.request.urlopen(req,timeout=20))
   if 'tags' in d: print(repo,[t['name'] for t in d['tags'][:10]])
   else: print(repo,'repository exists',d.get('name'))
   break
  except Exception as e:
   if suffix=='': print(repo,type(e).__name__,str(e)[:80])
PY"

